//! check: fail(E0301)
//! phase: resolve
//! conforms: type.method.root
//!
//! s166 — `any` is not a builtin method of `List`, so it comes from
//! `std.list`, and no std root is configured for this directory: E0301
//! naming the ways to configure one, never a builtin stand-in.

fn main() -> !int {
    let xs = [1, 2, 3]
    let b = xs.any(fn(x: int) { x > 1 })
    0
}

